pub fn cpu(draws:&[Draw],images:&[Image],c:&Camera,w:usize,h:usize,l:&[Light],ambient:[f64;3])->Result<Frame,String>{let asset=super::gltf_surface::Asset{streams:draws.iter().map(|d|super::node_ingest::transform(&d.stream,d.world)).collect::<Result<_,_>>()?,surfaces:draws.iter().map(|d|d.surface.clone()).collect(),images:images.to_vec(),metadata:serde_json::json!({"reference":"flat SAH primary visibility"})};let mut f=super::textured_bvh::render(&asset,c,w,h,l,ambient)?.frame;for p in &mut f.d{*p=((*p).clamp(0.,1.)*255.).round()/255.;}Ok(f)}
