#[derive(Debug,serde::Serialize)]pub struct Comparison{pub interior_samples:usize,pub coverage_mismatches:usize,pub max_rgb_error:f32,pub mean_rgb_error:f32,pub rgb_tolerance:f32,pub mean_tolerance:f32,pub coverage_fraction_tolerance:f32,pub passed:bool}
/// Exclude silhouette edges but report coverage mismatch across every pixel.
/// Narrow fixture test only: absolute max8/255, mean2/255 and coverage0.2%.
pub fn compare(g:&Frame,c:&Frame,w:usize,h:usize)->Result<Comparison,String>{if w<3||h<3||g.d.len()!=w*h*4||c.d.len()!=g.d.len()||g.d.iter().chain(&c.d).any(|v|!v.is_finite()){return Err("matched finite frames >=3x3".into());}let mut coverage=0usize;let mut samples=0usize;let mut maximum=0f32;let mut sum=0f64;for y in 0..h{for x in 0..w{let id=(y*w+x)*4;if (g.d[id+3]>0.5)!=(c.d[id+3]>0.5){coverage+=1;}if x==0||y==0||x+1==w||y+1==h{continue;}let interior=(-1isize..=1).all(|dy|(-1isize..=1).all(|dx|{let i=((y as isize+dy) as usize*w+(x as isize+dx) as usize)*4;g.d[i+3]>0.5&&c.d[i+3]>0.5}));if interior{for j in 0..3{let e=(g.d[id+j]-c.d[id+j]).abs();maximum=maximum.max(e);sum+=e as f64;samples+=1;}}}}let mean=if samples>0{(sum/samples as f64) as f32}else{f32::INFINITY};Ok(Comparison{interior_samples:samples,coverage_mismatches:coverage,max_rgb_error:maximum,mean_rgb_error:mean,rgb_tolerance:8./255.,mean_tolerance:2./255.,coverage_fraction_tolerance:0.002,passed:samples>0&&maximum<=8./255.&&mean<=2./255.&&coverage as f64/(w*h) as f64<=0.002})}
